targets.rawSql:
SELECT date_trunc('hour', executed_at) AS time, count(*) AS queries
FROM meta.query_log WHERE $__timeFilter(executed_at)
GROUP BY 1 ORDER BY 1;

SELECT executed_at AS "time", widget, query_name AS "query", error_message AS "error"
FROM meta.query_log WHERE status='FAILED'
ORDER BY executed_at DESC LIMIT 20;
